// src/pages/mainboard/MainBoardPage.jsx

import React, { useState } from 'react';
import { startWatcher, stopWatcher } from '../../api/WatcherApi';
import { useWatchedFolders } from '../../hooks/UseWatchedFolders';

function MainBoardPage() {
  // TODO: 나중에 이 값들은 백엔드/상태에서 가져오도록 변경
  const [protectionStatus] = useState('안전');
  const [lastScan] = useState('2시간 전');
  const [scanProgress, setScanProgress] = useState(0);
  const [isScanning, setIsScanning] = useState(false);

  // 🔹 감시 대상 폴더: 공통 훅 사용 (localStorage 연동)
  const {
    folders,
    promptAndAddFolder,
    removeFolder,
  } = useWatchedFolders();

  // 🔹 (임시) 더미 최근 이벤트 – 나중에 /logs 연동으로 교체
  const [recentEvents] = useState([
    {
      id: 1,
      time: '5분 전',
      path: '/Users/.../ransom.exe',
      level: 'danger',
      message: '랜섬웨어 의심 행위 탐지',
    },
    {
      id: 2,
      time: '12분 전',
      path: '/Users/.../doc/important.docx',
      level: 'warning',
      message: '평소와 다른 대량 파일 변경',
    },
  ]);

  // ================== 검사 시작 ==================
  const handleScanNow = async () => {
    try {
      const target = folders[0]; // 일단 첫 번째 폴더를 대상으로 사용

      if (!target) {
        alert(
          '감시할 폴더가 없습니다.\n먼저 "폴더 추가"에서 경로를 등록해주세요.'
        );
        return;
      }

      if (!target.path) {
        alert('폴더 경로 정보가 없습니다.');
        return;
      }

      setIsScanning(true);
      setScanProgress(5); // UI용 임시값

      const result = await startWatcher(target.path);
      console.log('startWatcher result:', result);

      // TODO: 백엔드 응답에 따라 진행률/상태 갱신
      setScanProgress(30);
    } catch (e) {
      console.error(e);
      alert('검사 시작 중 오류가 발생했습니다.\n' + e.message);
    } finally {
      setIsScanning(false);
    }
  };

  // ================== 검사 중지 ==================
  const handlePause = async () => {
    try {
      const result = await stopWatcher();
      console.log('stopWatcher result:', result);
      // TODO: 진행률/상태 갱신
    } catch (e) {
      console.error(e);
      alert('검사 중지 중 오류가 발생했습니다.\n' + e.message);
    }
  };

  // ================== 폴더 추가/삭제 ==================
  const handleAddFolder = () => {
    // 공통 훅의 prompt 기반 추가 사용
    promptAndAddFolder();
  };

  const handleRemoveFolder = (id) => {
    removeFolder(id);
  };

  return (
    <div className="mainboard-root">
      {/* 상단 헤더 영역 */}
      <header className="mainboard-header">
        <h1>WatchService Agent</h1>
        <div className="status-summary">
          <span className="status-label">보호 상태:</span>
          <span className="status-value">{protectionStatus}</span>
          <span className="status-last-scan">마지막 검사: {lastScan}</span>
        </div>
      </header>

      <div className="mainboard-body">
        {/* 좌측: 보호 상태 + 폴더 */}
        <section className="main-left">
          {/* 보호 상태 패널 */}
          <div className="status-panel">
            <div className="panel-header">
              <h2>실시간 보호 상태</h2>
            </div>

            <div className="status-body">
              <div className="status-left">
                <div
                  className="status-dot"
                  style={{
                    backgroundColor: protectionStatus === '안전' ? '#22c55e' : '#eab308',
                  }}
                />
                <span className="status-text">{protectionStatus}</span>
              </div>
              <div className="status-right">
                <div className="scan-controls">
                  <button
                    className="btn"
                    onClick={handleScanNow}
                    disabled={isScanning}
                  >
                    {isScanning ? '검사 중...' : '지금 검사'}
                  </button>

                  <button className="btn" onClick={handlePause}>
                    일시 중지
                  </button>
                </div>

                <div className="scan-progress">
                  <div className="scan-progress-bar">
                    <div
                      className="scan-progress-fill"
                      style={{ width: `${scanProgress}%` }}
                    />
                  </div>
                  <div className="scan-progress-text">
                    진행률: {scanProgress}%
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* 감시 대상 폴더 패널 */}
          <div className="folder-panel">
            <div className="panel-header">
              <h2>감시 대상 폴더</h2>
            </div>
            <div className="folder-list">
              {folders.map((f) => (
                <div key={f.id} className="folder-item">
                  <div className="folder-name">
                    {f.name}
                    <div
                      style={{
                        fontSize: '11px',
                        color: '#9ca3af',
                        marginTop: '2px',
                      }}
                    >
                      {f.path}
                    </div>
                  </div>
                  <button
                    className="btn-icon"
                    onClick={() => handleRemoveFolder(f.id)}
                  >
                    삭제
                  </button>
                </div>
              ))}
            </div>
            <button className="btn btn-outline" onClick={handleAddFolder}>
              폴더 추가
            </button>
          </div>
        </section>

        {/* 우측: 최근 이벤트 패널 (임시) */}
        <section className="main-right">
          <div className="recent-events-panel">
            <div className="panel-header">
              <h2>최근 탐지 이벤트</h2>
            </div>
            <div className="recent-events-list">
              {recentEvents.map((ev) => (
                <div key={ev.id} className="event-item">
                  <div className="event-main">
                    <span className="event-time">{ev.time}</span>
                    <span className="event-message">{ev.message}</span>
                  </div>
                  <div className="event-sub">
                    <span className="event-path">{ev.path}</span>
                    <span
                      className={
                        'event-level ' +
                        (ev.level === 'danger'
                          ? 'event-level-danger'
                          : 'event-level-warning')
                      }
                    >
                      {ev.level === 'danger' ? '위험' : '주의'}
                    </span>
                  </div>
                </div>
              ))}
              {recentEvents.length === 0 && (
                <p style={{ fontSize: 13, color: '#9ca3af' }}>
                  아직 탐지된 이벤트가 없습니다.
                </p>
              )}
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}

export default MainBoardPage;
